# momentum and a Newton-Schulz method; the auxiliary Adam takes betas and eps.
_MUON_HALF_KEYS = ("lr", "momentum", "weight_decay", "ns_method")
_ADAM_HALF_KEYS = ("lr", "betas", "eps", "weight_decay")

